468	    /**
469	     * The owner's Luhn check digit: a single digit ({@code 0}-{@code 9}) computed with the
470	     * standard Luhn algorithm over the decimal digits contained in the {@code customerCode}
471	     * (non-digit characters are ignored).
472	     *
473	     * @return the Luhn check digit, or {@code null} if the customer code has not been assigned
474	     */
475	    public Integer getCheckDigit() {
476	        if (this.customerCode == null) {
477	            return null;
478	        }
479	        int sum = 0;
480	        boolean dbl = true;
481	        for (int i = this.customerCode.length() - 1; i >= 0; i--) {
482	            char c = this.customerCode.charAt(i);
483	            if (c < '0' || c > '9') {
484	                continue;
485	            }
486	            int d = c - '0';
487	            if (dbl) {
488	                d *= 2;
489	                if (d > 9) {
490	                    d -= 9;
491	                }
492	            }
493	            sum += d;
494	            dbl = !dbl;
495	        }
496	        return (10 - (sum % 10)) % 10;
497	    }
498	
499	    /**
500	     * The owner's membership points, starting at {@code 0}. The owner gains {@code 2} when
501	     * they carry an email address, {@code 1} when they have no namesakes
502	     * ({@code namesakeCount} is {@code 0}), {@code 2} for a household of {@code 3} or more
503	     * members ({@code householdSize}), and {@code 3} for tenure of at least one elapsed
504	     * fiscal year (the {@code registrationDate}'s fiscal year precedes the current fiscal
505	     * year, the fiscal year starting on 1 July). Because a newly created owner is still in
506	     * the current fiscal year, a new owner can score at most {@code 5} points.
507	     *
508	     * @return the membership points
509	     */
510	    public Integer getMembershipPoints() {
511	        int points = 0;
512	        boolean hasEmail = this.email != null && !this.email.isBlank();
513	        if (hasEmail) {
514	            points += 2;
515	        }
516	        boolean noNamesakes = this.namesakeCount != null && this.namesakeCount == 0;
517	        if (noNamesakes) {
518	            points += 1;
519	        }
520	        if (this.householdSize != null && this.householdSize >= 3) {
521	            points += 2;
522	        }
523	        if (this.registrationDate != null
524	            && fiscalYearOf(LocalDate.now()) - fiscalYearOf(this.registrationDate) >= 1) {
525	            points += 3;
526	        }
527	        return points;
528	    }
529	
530	    /**
531	     * The owner's numeric membership level, from {@code 1} to {@code 4}, derived from the
532	     * {@link #getMembershipPoints() membership points}: {@code 1} for {@code 0-1} points,
533	     * {@code 2} for {@code 2-3} points, {@code 3} for {@code 4-5} points, and {@code 4} for
534	     * {@code 6} or more points. Because a newly created owner has zero tenure, a new owner
535	     * scores at most {@code 5} points and so never exceeds level {@code 3}; level {@code 4}
536	     * is reserved for owners whose tenure spans at least one elapsed fiscal year.
537	     *
538	     * <p>When a {@link #getMembershipLevelCap() membership-level cap} has been assigned the
539	     * points-derived level is capped to it, so an owner admitted into an existing household can never
540	     * exceed one level above their household's highest member.
541	     *
542	     * @return the membership level
543	     */
544	    public Integer getMembershipLevel() {
545	        int level = pointsMembershipLevel();
546	        if (this.membershipLevelCap != null && level > this.membershipLevelCap) {
547	            return this.membershipLevelCap;
548	        }
549	        return level;
550	    }
551	
552	    /**
553	     * The membership level derived purely from the {@link #getMembershipPoints() membership points},
554	     * before any {@link #getMembershipLevelCap() household cap} is applied.
555	     *
556	     * @return the uncapped, points-derived membership level
557	     */
558	    private int pointsMembershipLevel() {
559	        int points = getMembershipPoints();
560	        if (points >= 6) {
561	            return 4;
562	        }
563	        if (points >= 4) {
564	            return 3;
565	        }
566	        if (points >= 2) {
567	            return 2;
568	        }
569	        return 1;
570	    }
571	
572	    /**
573	     * The owner's preferred contact channel: {@code "EMAIL"} when the owner carries an
574	     * email address, otherwise {@code "PHONE"}.
575	     *
576	     * @return {@code "EMAIL"} when an email is present, otherwise {@code "PHONE"}
577	     */
578	    public String getContactPreference() {
579	        boolean hasEmail = this.email != null && !this.email.isBlank();
580	        return hasEmail ? "EMAIL" : "PHONE";
581	    }
582	
583	    /**
584	     * The owner's identity key: the single derived value used for duplicate detection. It is the
585	     * lower-case, 64-character hex SHA-256 digest over
586	     * {@code normalizedTelephone + "|" + lowerEmail + "|" + soundex(lastName)}, where the telephone
587	     * is the already-normalized stored value, the email is lower-cased (a {@code null} email is
588	     * rendered as the empty string) and the last name is reduced to its Soundex code. Two owners are
589	     * duplicates only when their whole identity keys are equal; because the telephone is part of the
590	     * key, two owners sharing a last name (Soundex) but with different telephones have different
591	     * identity keys and so are not hard duplicates.
592	     *
593	     * @return the derived identity key
594	     */
595	    public String getIdentityKey() {
596	        String telephonePart = this.telephone == null ? "" : this.telephone;
597	        String emailPart = this.email == null ? "" : this.email.toLowerCase(Locale.ROOT);
598	        String soundexPart = soundex(getLastName());
599	        return sha256Hex(telephonePart + "|" + emailPart + "|" + soundexPart);
600	    }
601	
602	    /**
603	     * Returns the lower-case, 64-character hex SHA-256 digest of the UTF-8 bytes of {@code input}.
604	     *
605	     * @param input the value to hash
606	     * @return the full hex digest
607	     */
608	    private static String sha256Hex(String input) {
609	        try {
610	            byte[] digest = MessageDigest.getInstance("SHA-256")
611	                .digest(input.getBytes(StandardCharsets.UTF_8));
612	            StringBuilder sb = new StringBuilder(digest.length * 2);
613	            for (byte b : digest) {
614	                sb.append(String.format("%02x", b));
615	            }
616	            return sb.toString();
617	        }
618	        catch (NoSuchAlgorithmException e) {
619	            throw new IllegalStateException("SHA-256 not available", e);
620	        }
621	    }
622	
623	    /**
624	     * Computes the American Soundex code of a name: the first letter followed by three digits that
625	     * phonetically encode the remaining consonants. Non-letters are ignored, {@code h} and {@code w}
626	     * are transparent (letters either side of them are treated as adjacent) and vowels reset the
627	     * run so a repeated code across a vowel is encoded twice. A {@code null} or letter-free value
628	     * yields the empty string.
629	     *
630	     * @param value the name to encode
631	     * @return the Soundex code, or the empty string when there is no letter to encode
632	     */
633	    public static String soundex(String value) {
634	        if (value == null) {
635	            return "";
636	        }
637	        StringBuilder letters = new StringBuilder();
638	        for (int i = 0; i < value.length(); i++) {
639	            char c = Character.toUpperCase(value.charAt(i));
640	            if (c >= 'A' && c <= 'Z') {
641	                letters.append(c);
642	            }
643	        }
644	        if (letters.length() == 0) {
645	            return "";
646	        }
647	        StringBuilder code = new StringBuilder();
648	        char first = letters.charAt(0);
649	        code.append(first);
650	        char last = soundexDigit(first);
651	        for (int i = 1; i < letters.length() && code.length() < 4; i++) {
652	            char c = letters.charAt(i);
653	            if (c == 'H' || c == 'W') {
654	                // Transparent: leave the previous code in place so letters either side stay adjacent.
655	                continue;
656	            }
657	            char digit = soundexDigit(c);
658	            if (digit != '0') {
659	                if (digit != last) {
660	                    code.append(digit);
661	                }
662	                last = digit;
663	            }
664	            else {
665	                // A vowel breaks the run so a following letter with the same code is encoded again.
666	                last = '0';
667	            }
668	        }
669	        while (code.length() < 4) {
670	            code.append('0');
671	        }
672	        return code.toString();
673	    }
674	
675	    /**
676	     * Maps a single upper-case letter to its Soundex digit, or {@code '0'} for vowels and the
677	     * uncoded letters {@code h} and {@code w}.
678	     */
679	    private static char soundexDigit(char c) {
680	        switch (c) {
681	            case 'B': case 'F': case 'P': case 'V':
682	                return '1';
683	            case 'C': case 'G': case 'J': case 'K': case 'Q': case 'S': case 'X': case 'Z':
684	                return '2';
685	            case 'D': case 'T':
686	                return '3';
687	            case 'L':
688	                return '4';
689	            case 'M': case 'N':
690	                return '5';
691	            case 'R':
692	                return '6';
693	            default:
694	                return '0';
695	        }
696	    }
697	
698	    /**
699	     * City -> canonical region, the fixed ground truth for deriving locality.
700	     */
701	    private static final Map<String, String> CITY_REGION = Map.of(
702	        "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
703	
704	    /**
705	     * Region -> inclusive 4-digit postcode range {@code {low, high}}, the fixed ground truth for
706	     * deriving locality from the postcode ahead of the city.
707	     */
708	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
709	        "NSW", new int[] {2000, 2099}, "VIC", new int[] {3000, 3099}, "QLD", new int[] {4000, 4099});
710	
711	    /**
712	     * The owner's locality: the canonical region resolved by the postcode range first
713	     * ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}), falling back to the
714	     * fixed city-to-region table ({@code Sydney->NSW}, {@code Melbourne->VIC},
715	     * {@code Brisbane->QLD}) when the postcode is absent or in no known range, or {@code "UNKNOWN"}
716	     * when the city is not in the table either. The postcode takes precedence so cities that share a
717	     * name are disambiguated by their postcode's region.
718	     *
719	     * @return the canonical region string, or {@code "UNKNOWN"}
720	     */
721	    public String getLocality() {
722	        String byPostcode = regionForPostcode(this.postcode);
723	        if (byPostcode != null) {
724	            return byPostcode;
725	        }
726	        return CITY_REGION.getOrDefault(this.city, "UNKNOWN");
727	    }
728	
729	    /**
730	     * Region -> IANA timezone name, the fixed ground truth for deriving the owner's timezone from
731	     * its locality.
732	     */
733	    private static final Map<String, String> REGION_TIMEZONE = Map.of(
734	        "NSW", "Australia/Sydney", "VIC", "Australia/Melbourne", "QLD", "Australia/Brisbane");
735	
736	    /**
737	     * The owner's timezone: the IANA name resolved from the {@link #getLocality() locality} via the
738	     * fixed region-to-timezone table ({@code NSW->Australia/Sydney}, {@code VIC->Australia/Melbourne},
739	     * {@code QLD->Australia/Brisbane}), or {@code null} when the locality is not one of these regions
740	     * (e.g. {@code "UNKNOWN"}).
741	     *
742	     * @return the IANA timezone name, or {@code null}
743	     */
744	    public String getTimezone() {
745	        return REGION_TIMEZONE.get(getLocality());
746	    }
747	
748	    /**
749	     * Region whose postcode range contains the given postcode, or {@code null} when the postcode is
750	     * absent, not a 4-digit number, or in no known range.
751	     *
752	     * @param postcode the owner's postcode (may be {@code null})
753	     * @return the matching region, or {@code null}
754	     */
755	    private static String regionForPostcode(String postcode) {
756	        if (postcode == null || !postcode.matches("\\d{4}")) {
757	            return null;
758	        }
759	        int value = Integer.parseInt(postcode);
760	        for (Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
761	            int[] range = entry.getValue();
762	            if (value >= range[0] && value <= range[1]) {
763	                return entry.getKey();
764	            }
765	        }
766	        return null;
767	    }
768	
769	    protected Set<Pet> getPetsInternal() {
770	        if (this.pets == null) {
771	            this.pets = new HashSet<>();
772	        }
773	        return this.pets;
774	    }
775	
776	    protected void setPetsInternal(Set<Pet> pets) {
777	        this.pets = pets;
778	    }
779	
780	    public List<Pet> getPets() {
781	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
782	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
783	        return Collections.unmodifiableList(sortedPets);
784	    }
785	
786	    public void setPets(List<Pet> pets) {
787	        this.pets = new HashSet<>(pets);
788	    }
789	
790	    public void addPet(Pet pet) {
791	        getPetsInternal().add(pet);
792	        pet.setOwner(this);
793	    }
794	
795	    /**
796	     * Return the Pet with the given name, or null if none found for this Owner.
797	     *
798	     * @param name to test
799	     * @return true if pet name is already in use
800	     */
801	    public Pet getPet(String name) {
802	        return getPet(name, false);
803	    }
804	
805	    /**
806	     * Return the Pet with the given name, or null if none found for this Owner.
807	     *
808	     * @param name to test
809	     * @return true if pet name is already in use
810	     */
811	    public Pet getPet(String name, boolean ignoreNew) {
812	        name = name.toLowerCase();
813	        for (Pet pet : getPetsInternal()) {
814	            if (!ignoreNew || !pet.isNew()) {
815	                String compName = pet.getName();
816	                compName = compName.toLowerCase();
817	                if (compName.equals(name)) {
818	                    return pet;
819	                }
820	            }
821	        }
822	        return null;
823	    }
824	
825	    public Pet getPet(Integer petId) {
826	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
827	    }
828	
829	    @Override
830	    public String toString() {
831	        return new ToStringCreator(this)
832	
833	            .append("id", this.getId())
834	            .append("new", this.isNew())
835	            .append("lastName", this.getLastName())
836	            .append("firstName", this.getFirstName())
837	            .append("address", this.address)
838	            .append("city", this.city)
839	            .append("telephone", this.telephone)
840	            .append("email", this.email)
841	            .toString();
842	    }
843	}
